// Builds the directory window (packages/client/window) into one self-contained HTML document and writes it as a string
// to packages/client/src/window.generated.ts, which the connector serves as the ui:// resource (APP.md, "The window").
// The generated file is not committed: typecheck, test, build:mcpb and build:bin each build it first, so it always
// matches its sources. The version is read here once, from packages/client/package.json: the card names it, and the
// other two build scripts import it from here and write it into the executables and the bundle.
//
//   node scripts/build-window.mjs
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { build, transform } from 'esbuild';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const client = join(root, 'packages', 'client');
/** The client's version, read once: the card names it, and the executables and the bundle carry it. */
export const { version } = JSON.parse(readFileSync(join(client, 'package.json'), 'utf8'));
/** The card bundles these; the comment says so, as the page says what it loads (nothing from another server). */
const NOTICE =
  '<!-- Quilt, Apache-2.0. Bundles @modelcontextprotocol/ext-apps (MIT), @modelcontextprotocol/sdk (MIT) and zod (MIT). -->';

/** The document, written to the generated file and returned. */
export async function buildWindow() {
  const js = await build({
    entryPoints: [join(client, 'window', 'window.ts')],
    bundle: true,
    format: 'iife',
    minify: true,
    target: 'es2020',
    write: false,
    tsconfig: join(client, 'window', 'tsconfig.json'),
    define: { __QUILT_VERSION__: JSON.stringify(version) },
    legalComments: 'none',
    logLevel: 'warning',
  });
  const css = await transform(readFileSync(join(client, 'window', 'window.css'), 'utf8'), {
    loader: 'css',
    minify: true,
  });
  const script = js.outputFiles[0].text.replace(/<\/script/gi, '<\\/script');
  const html = `<!doctype html>${NOTICE}<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="light dark"><title>Quilt</title><style>${css.code}</style></head><body><div id="window"></div><script>${script}</script></body></html>`;
  const out = `// GENERATED by scripts/build-window.mjs from packages/client/window, and not committed. Edit the sources.\nexport const WINDOW_HTML: string = ${JSON.stringify(html)};\n`;
  writeFileSync(join(client, 'src', 'window.generated.ts'), out);
  return html;
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const html = await buildWindow();
  console.log(`built the window, ${html.length} bytes`);
}
